def minCostToMoveChips(position):
    # Count chips on even and odd positions
    even = 0
    odd = 0
    for chip in position:
        if chip % 2 == 0:
            even += 1
        else:
            odd += 1
    # The minimum of the two is the answer
    return min(even, odd)
